import { Component, computed, inject, input, signal, OnInit } from '@angular/core';
import { forkJoin } from 'rxjs';
import { CommonModule, DatePipe } from '@angular/common';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { QuillModule, ContentChange } from 'ngx-quill';
import { MensajeService } from '../../../../shared/services/mensaje.service';
import { AuthService } from '../../../../services/auth.service';
import { DocumentoService } from '../../../../services/documento.service';
import { PdfViewerComponent } from '../../../../shared/components/pdf-viewer/pdf-viewer.component';
import { ToastService } from '../../../../shared/services/toast.service';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';
import type { Mensaje } from '../../../../shared/models/mensaje.model';

@Component({
  selector: 'app-bitacora-notas',
  imports: [CommonModule, ReactiveFormsModule, QuillModule, DatePipe, PdfViewerComponent],
  templateUrl: './bitacora-notas.component.html',
})
export class BitacoraNotasComponent implements OnInit {
  private readonly mensajeService = inject(MensajeService);
  protected readonly authService = inject(AuthService);
  private readonly documentoService = inject(DocumentoService);
  private readonly toastService = inject(ToastService);
  readonly folio = input.required<string>();
  readonly notas = signal<Mensaje[]>([]);
  readonly puedeCrearNotas = computed(() => {
    const user = this.authService.currentUser();
    return user?.role === 'inversor';
  });
  readonly loading = signal(false);
  readonly mostrandoFormulario = signal(false);
  readonly editandoId = signal<number | null>(null);
  readonly documentosAdjuntos = signal<{ id: number; nombre: string }[]>([]);
  readonly subiendo = signal(false);
  readonly selectedDocId = signal<number | null>(null);
  readonly mostrarVisor = signal(false);

  readonly form = new FormGroup({
    titulo: new FormControl(''),
  });

  readonly contenido = signal('');

  ngOnInit(): void {
    this.cargarNotas();
  }

  cargarNotas(): void {
    this.loading.set(true);
    this.mensajeService.getNotas(this.folio()).subscribe({
      next: (res) => {
        this.notas.set(res.data);
        this.loading.set(false);
      },
      error: (err) => {
        this.loading.set(false);
        this.toastService.error(extractErrorMessage(err));
      },
    });
  }

  nuevaNota(): void {
    this.mostrandoFormulario.set(true);
    this.editandoId.set(null);
    this.form.reset({ titulo: '' });
    this.contenido.set('');
    this.documentosAdjuntos.set([]);
  }

  cancelar(): void {
    this.mostrandoFormulario.set(false);
    this.editandoId.set(null);
    this.form.reset({ titulo: '' });
    this.contenido.set('');
    this.documentosAdjuntos.set([]);
  }

  guardarNota(): void {
    if (!this.contenido().trim()) return;

    const html = this.contenido();
    const titulo = this.form.value.titulo ?? '';
    const payload = { contenido: html, tipo: 'nota' as const, titulo: titulo || undefined };
    const editando = this.editandoId();
    const obs$ = editando
      ? this.mensajeService.updateMensaje(editando, payload)
      : this.mensajeService.createMensaje(this.folio(), payload);

    obs$.subscribe({
      next: (mensaje) => {
        const docs = this.documentosAdjuntos();
        if (docs.length > 0 && !editando) {
          this.adjuntarDocumentos(mensaje.id, docs);
        } else {
          this.cargarNotas();
          this.cancelar();
          this.toastService.success(editando ? 'Nota actualizada' : 'Nota creada');
        }
      },
      error: (err) => this.toastService.error(extractErrorMessage(err)),
    });
  }

  private adjuntarDocumentos(mensajeId: number, docs: { id: number; nombre: string }[]): void {
    const attachCalls = docs.map(doc =>
      this.mensajeService.adjuntarDocumento(mensajeId, doc.id)
    );

    forkJoin(attachCalls).subscribe({
      next: () => {
        this.toastService.success('Nota guardada con documentos adjuntos');
        this.cargarNotas();
        this.cancelar();
      },
      error: () => {
        this.toastService.error('Error al adjuntar uno o más documentos');
        this.cargarNotas();
        this.cancelar();
      },
    });
  }

  editarNota(nota: Mensaje): void {
    this.mostrandoFormulario.set(true);
    this.editandoId.set(nota.id);
    this.documentosAdjuntos.set(nota.documentos.map(d => ({ id: d.id, nombre: d.nombreOriginal })));
    this.form.controls.titulo.setValue(nota.titulo ?? '');
    this.contenido.set(nota.contenido);
  }

  eliminarNota(id: number): void {
    if (!confirm('¿Eliminar esta nota?')) return;
    this.mensajeService.deleteMensaje(id).subscribe({
      next: () => {
        this.cargarNotas();
        this.toastService.success('Nota eliminada');
      },
      error: (err) => this.toastService.error(extractErrorMessage(err)),
    });
  }

  subirDocumento(event: Event): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;

    this.subiendo.set(true);
    this.documentoService.uploadDocumento(file).subscribe({
      next: (res) => {
        this.documentosAdjuntos.update(prev => [...prev, { id: res.id, nombre: res.nombre_original }]);
        this.subiendo.set(false);
        input.value = '';
      },
      error: (err) => {
        this.subiendo.set(false);
        this.toastService.error(extractErrorMessage(err));
      },
    });
  }

  quitarDocumento(index: number): void {
    this.documentosAdjuntos.update(prev => prev.filter((_, i) => i !== index));
  }

  onContentChanged(event: ContentChange): void {
    this.contenido.set(event.html || '');
  }

  verDocumento(docId: number): void {
    this.selectedDocId.set(docId);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
  }

  esAutor(nota: Mensaje): boolean {
    const user = this.authService.currentUser();
    return user ? nota.autor.id === user.id : false;
  }
}
